        (r'v_c=\sqrt{\frac{\mu}{r}}', T('Cancel m and solve for v.', 'Simplifier m et isoler v.', 'Cancelar m y despejar v.', 'نحذف m ونحل لإيجاد v.', 'Semplificare m e ricavare v.')),
